test('zero division error and recovery', async () => {
  clearAll();
  append('8');
  append('/');
  append('0');
  evaluate();
  const errorMsg = String(document.getElementById('display').textContent);
  assert.ok(errorMsg.includes('Division by zero'), 'error displayed');
  // after error, new valid input should work (no extra clearAll needed)
  append('1');
  append('+');
  append('1');
  evaluate();
  assert.equal(String(document.getElementById('display').textContent), '2');
});
